from collections import deque

def minPath(grid, k):
    n = len(grid)
    values = {val: (i, j) for i in range(n) for j in range(n)}
    min_path = None

    def dfs(current, path, visited):
        nonlocal min_path
        if len(path) == k:
            if min_path is None or path < min_path:
                min_path = path.copy()
            return
        i, j = current
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n:
                val = grid[ni][nj]
                if val not in visited:
                    visited.add(val)
                    path.append(val)
                    dfs((ni, nj), path, visited)
                    path.pop()
                    visited.remove(val)

    for i in range(n):
        for j in range(n):
            dfs((i, j), [grid[i][j]], {grid[i][j]})

    return min_path
